import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String op = sc.next();
        int a = sc.nextInt();
        int b = sc.nextInt();

        switch (op) {
            case "add" -> System.out.println("操作 たす");
            case "sub" -> System.out.println("操作 ひく");
            case "mul" -> System.out.println("操作 かける");
            case "div" -> System.out.println("操作 わる");
            default -> System.out.println("操作 ふめい");
        }

        int result = switch (op) {
            case "add" -> a + b;
            case "sub" -> a - b;
            case "mul" -> a * b;
            case "div" -> {
                if (b == 0) {
                    yield 0;
                }
                yield a / b;
            }
            default -> 0;
        };
        System.out.println("結果 " + result);

        char c = op.charAt(0);
        String mark = switch (c) {
            case 'a' -> "+";
            case 's' -> "-";
            case 'm' -> "*";
            case 'd' -> "/";
            default -> "?";
        };
        System.out.println("記号 " + mark);

        StringBuilder sb = new StringBuilder("流れ ");
        switch (c) {
            case 'a':
                sb.append("a");
            case 's':
                sb.append("s");
            case 'm':
                sb.append("m");
            default:
                sb.append("d");
        }
        System.out.println(sb);
    }
}

