import java.util.Scanner;

interface Named {
    String jp();
}

enum Signal implements Named {
    RED, YELLOW, GREEN;

    @Override
    public String jp() {
        return switch (this) {
            case RED -> "赤";
            case YELLOW -> "黄";
            case GREEN -> "青";
        };
    }

    Signal next() {
        return values()[(ordinal() + 1) % values().length];
    }
}

public class Main {
    static void show(String label, Named n) {
        System.out.println(label + " " + n.jp());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        String b = sc.next();

        Signal sa = Signal.valueOf(a);
        Signal sb = Signal.valueOf(b);

        show("1つ目", sa);
        show("2つ目", sb);
        System.out.println("同じ " + (sa == sb));
        System.out.println("次 " + sa.next().name());

        String list = "一覧";
        for (Signal s : Signal.values()) {
            list += " " + s.name();
        }
        System.out.println(list);
    }
}

